// Brand colours too dark to read on the dark theme. They are drawn in the page's ink instead,
// which is near-black on the light theme and near-white on the dark one.
const DARK_FILLS = ["#1a1919", "#00546b", "#130754", "#4e4e4e", "#616262", "#767677", "#3c3a3e", "#424143", "#4d5a31"];

/** The logo's SVG markup, with its darkest brand colours following the theme's ink. */
export function themedBody(logo: Logo) {
  let body = logo.body;
  for (const hex of DARK_FILLS) body = body.replaceAll(new RegExp(hex, "gi"), "currentColor");
  // Logos with no fill of their own (LangChain) inherit the ink too.
  if (!/fill=/.test(body)) body = `<g fill="currentColor">${body}</g>`;
  return body;
}
